<?php
require_once dirname(__DIR__) . '/middleware/bootstrap.php';
require_role('admin');
$db=Database::connection();$id=(int)($_GET['id']??$_POST['id']??0);$course=$id?(new Course($db))->get($id):null;$isNew=!$id;
if($id&&!$course){http_response_code(404);exit('Course not found.');}
$departments=$db->query('SELECT id,name FROM departments ORDER BY name')->fetchAll();
$availableCourses=$db->prepare('SELECT id,code,title FROM courses WHERE id<>? ORDER BY code');$availableCourses->execute([$id]);$allCourses=$availableCourses->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{
  $code=strtoupper(post_string('code',30));$title=post_string('title',180);$credits=(int)($_POST['credits']??0);$faculty=post_string('faculty_name',160);$semester=(int)($_POST['semester']??0);$capacity=(int)($_POST['capacity']??0);$department=(int)($_POST['department_id']??0)?:null;
  if(!preg_match('/^[A-Z0-9_-]{2,30}$/',$code)||strlen($title)<2||strlen($faculty)<2||$credits<1||$credits>30||$semester<1||$semester>12||$capacity<1)throw new DomainException('Check course code, title, faculty, credits, semester, and capacity.');
  if($id){$stmt=$db->prepare("SELECT COUNT(*) FROM registrations WHERE course_id=? AND term_id=(SELECT id FROM academic_terms WHERE is_current=1 LIMIT 1) AND status IN ('pending','approved')");$stmt->execute([$id]);if((int)$stmt->fetchColumn()>$capacity)throw new DomainException('Capacity cannot be lower than the number of active registrations in the current term.');}
  $db->beginTransaction();
  if($id){$stmt=$db->prepare('UPDATE courses SET code=?,title=?,description=?,credits=?,faculty_name=?,department_id=?,semester=?,capacity=? WHERE id=?');$stmt->execute([$code,$title,post_string('description',3000),$credits,$faculty,$department,$semester,$capacity,$id]);}
  else{$stmt=$db->prepare('INSERT INTO courses(code,title,description,credits,faculty_name,department_id,semester,capacity) VALUES(?,?,?,?,?,?,?,?)');$stmt->execute([$code,$title,post_string('description',3000),$credits,$faculty,$department,$semester,$capacity]);$id=(int)$db->lastInsertId();}
  $db->prepare('DELETE FROM course_schedules WHERE course_id=?')->execute([$id]);
  $days=$_POST['schedule_day']??[];$starts=$_POST['schedule_start']??[];$ends=$_POST['schedule_end']??[];$rooms=$_POST['schedule_room']??[];
  foreach($days as $i=>$day){$hasSchedule=$day!==''||!empty($starts[$i])||!empty($ends[$i]);if(!$hasSchedule)continue;if($day===''||empty($starts[$i])||empty($ends[$i])||(int)$day<1||(int)$day>7||$starts[$i]>=$ends[$i])throw new DomainException('Each schedule needs a valid day and an end time after its start.');$db->prepare('INSERT INTO course_schedules(course_id,day_of_week,starts_at,ends_at,room) VALUES(?,?,?,?,?)')->execute([$id,(int)$day,$starts[$i],$ends[$i],substr((string)($rooms[$i]??''),0,80)]);}
  $db->prepare('DELETE FROM course_prerequisites WHERE course_id=?')->execute([$id]);
  foreach(array_unique(array_map('intval',$_POST['prerequisites']??[])) as $pre){if($pre===$id)throw new DomainException('A course cannot be its own prerequisite.');$db->prepare('INSERT INTO course_prerequisites(course_id,prerequisite_course_id) VALUES(?,?)')->execute([$id,$pre]);}
  $db->prepare('INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,ip_address) VALUES(?,?,?,?,?)')->execute([current_user_id(),$course?'course_updated':'course_created','course',$id,$_SERVER['REMOTE_ADDR']??null]);
  $db->commit();flash('success','Course saved.');redirect('admin/courses.php');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($isNew)$id=0;if(!$e instanceof DomainException&&!($e instanceof PDOException&&(string)$e->getCode()==='23000'))error_log('Course save error: '.$e->getMessage());$error=$e instanceof DomainException?$e->getMessage():($e instanceof PDOException&&(string)$e->getCode()==='23000'?'That course code is already in use.':'Course could not be saved. Check all fields and try again.');}
}
$schedules=$course['schedules']??[];$prereqIds=array_column($course['prerequisites']??[],'id');
page_start($id?'Edit course':'Add course','admin/courses.php');
?>
<div class="content-width"><?php page_title($id?'Edit course':'Add course','Configure eligibility, capacity, prerequisites, and meeting times.'); ?>
<div class="panel"><div class="row"><div class="col-xl-10"><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<form method="post" id="courseForm"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>">
<div class="row g-3"><div class="col-md-4"><label class="form-label">Course code</label><input class="form-control" name="code" required maxlength="30" value="<?= e($course['code']??'') ?>"></div><div class="col-md-8"><label class="form-label">Course title</label><input class="form-control" name="title" required maxlength="180" value="<?= e($course['title']??'') ?>"></div><div class="col-md-6"><label class="form-label">Department (blank = all)</label><select class="form-select" name="department_id"><option value="">All departments</option><?php foreach($departments as $d): ?><option value="<?= (int)$d['id'] ?>" <?= (int)($course['department_id']??0)===(int)$d['id']?'selected':'' ?>><?= e($d['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Semester</label><select class="form-select" name="semester"><?php for($s=1;$s<=12;$s++): ?><option value="<?= $s ?>" <?= (int)($course['semester']??1)===$s?'selected':'' ?>><?= $s ?></option><?php endfor; ?></select></div><div class="col-md-3"><label class="form-label">Credits</label><input class="form-control" type="number" name="credits" min="1" max="30" required value="<?= e($course['credits']??3) ?>"></div><div class="col-md-6"><label class="form-label">Faculty name</label><input class="form-control" name="faculty_name" required maxlength="160" value="<?= e($course['faculty_name']??'') ?>"></div><div class="col-md-6"><label class="form-label">Seat capacity</label><input class="form-control" type="number" name="capacity" min="1" required value="<?= e($course['capacity']??40) ?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="3"><?= e($course['description']??'') ?></textarea></div></div>
<hr><div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h6 fw-bold mb-0">Weekly schedule</h2><button class="btn btn-sm btn-outline-primary" type="button" id="addSchedule">Add meeting</button></div><div id="scheduleRows"><?php $scheduleRows=$schedules?:[[]];foreach($scheduleRows as $s): ?><div class="row g-2 mb-2 schedule-row"><div class="col-md-3"><select class="form-select" name="schedule_day[]"><option value="">Day</option><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $i=>$day): ?><option value="<?= $i+1 ?>" <?= (int)($s['day_of_week']??0)===$i+1?'selected':'' ?>><?= e($day) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><input class="form-control" type="time" name="schedule_start[]" value="<?= e(isset($s['starts_at'])?substr($s['starts_at'],0,5):'') ?>"></div><div class="col-md-2"><input class="form-control" type="time" name="schedule_end[]" value="<?= e(isset($s['ends_at'])?substr($s['ends_at'],0,5):'') ?>"></div><div class="col-md-4"><input class="form-control" name="schedule_room[]" placeholder="Room" maxlength="80" value="<?= e($s['room']??'') ?>"></div><div class="col-md-1"><button class="btn btn-outline-danger remove-schedule" type="button" aria-label="Remove meeting"><i class="bi bi-x-lg"></i></button></div></div><?php endforeach; ?></div>
<div class="mt-3"><label class="form-label">Prerequisites</label><select class="form-select" name="prerequisites[]" multiple size="5"><?php foreach($allCourses as $pre): ?><option value="<?= (int)$pre['id'] ?>" <?= in_array($pre['id'],$prereqIds)?'selected':'' ?>><?= e($pre['code'].' · '.$pre['title']) ?></option><?php endforeach; ?></select><div class="form-text">Use Ctrl (Windows) to select multiple.</div></div>
<div class="mt-4"><button class="btn btn-primary">Save course</button> <a class="btn btn-light" href="<?= e(url('admin/courses.php')) ?>">Cancel</a></div></form>
</div></div></div></div>
<template id="scheduleTemplate"><div class="row g-2 mb-2 schedule-row"><div class="col-md-3"><select class="form-select" name="schedule_day[]"><option value="">Day</option><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $i=>$day): ?><option value="<?= $i+1 ?>"><?= e($day) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><input class="form-control" type="time" name="schedule_start[]"></div><div class="col-md-2"><input class="form-control" type="time" name="schedule_end[]"></div><div class="col-md-4"><input class="form-control" name="schedule_room[]" placeholder="Room" maxlength="80"></div><div class="col-md-1"><button class="btn btn-outline-danger remove-schedule" type="button"><i class="bi bi-x-lg"></i></button></div></div></template>
<script>document.getElementById('addSchedule').addEventListener('click',()=>document.getElementById('scheduleRows').append(document.getElementById('scheduleTemplate').content.cloneNode(true)));document.getElementById('scheduleRows').addEventListener('click',e=>{if(e.target.closest('.remove-schedule'))e.target.closest('.schedule-row').remove()});</script>
<?php page_end(); ?>
